namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Specializes in algorithms and distributed systems with 15 years of teaching experience.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Kim", Title = "Associate Professor", Bio = "Expert in machine learning and artificial intelligence. Published over 40 research papers.", Email = "rkim@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Lopez", Title = "Professor", Bio = "Renowned mathematician focusing on topology and abstract algebra.", Email = "mlopez@university.edu" },
            new() { Id = 4, Name = "Dr. James Wright", Title = "Assistant Professor", Bio = "Quantum physics researcher with experience at CERN.", Email = "jwright@university.edu" },
            new() { Id = 5, Name = "Dr. Sarah Miller", Title = "Professor", Bio = "Award-winning author and literary critic specializing in modern American fiction.", Email = "smiller@university.edu" },
            new() { Id = 6, Name = "Dr. David Park", Title = "Associate Professor", Bio = "Historian of early modern Europe with expertise in the Renaissance period.", Email = "dpark@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn fundamental programming concepts using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, sorting, and complexity analysis.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, Instructor = _instructors[1], Department = _departments[0], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications. Prerequisite: MATH 201.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", DepartmentId = 2, Instructor = _instructors[2], Department = _departments[1] },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, waves, and thermodynamics. Calculus-based introductory physics.", Credits = 4, Schedule = "MWF 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2], IsFeatured = true },
            new() { Id = 7, Code = "PHYS 320", Title = "Quantum Mechanics", Description = "Wave functions, Schrödinger equation, angular momentum, and hydrogen atom.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, Instructor = _instructors[3], Department = _departments[2] },
            new() { Id = 8, Code = "ENG 110", Title = "College Writing", Description = "Develop critical thinking and writing skills through essay composition and peer review.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 9, Code = "ENG 350", Title = "American Novel", Description = "Survey of the American novel from the 19th century to the present.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 4, Instructor = _instructors[4], Department = _departments[3] },
            new() { Id = 10, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times through the Renaissance.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4] },
            new() { Id = 11, Code = "HIST 280", Title = "Renaissance Europe", Description = "In-depth study of European culture, politics, and society during the Renaissance.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", DepartmentId = 5, Instructor = _instructors[5], Department = _departments[4], IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

