@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request has been received. You will receive a confirmation via your student email.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
    }
    else
    {
        <p class="text-muted mb-4">Complete the form below to request enrollment in a course.</p>

        <form method="post" class="col-md-8">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., S12345678" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="Model.CourseId" class="form-select" required>
                    <option value="">— Select a course —</option>
                    @foreach (var course in Catalog.GetCourses())
                    {
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code — @course.Title</option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-link">Cancel</a>
        </form>
    }
</div>

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    public bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Check if this is a POST with valid data
        if (Model.CourseId > 0
            && !string.IsNullOrWhiteSpace(Model.StudentName)
            && !string.IsNullOrWhiteSpace(Model.StudentId))
        {
            Submitted = Catalog.SubmitEnrollmentRequest(Model);
        }
    }
}

